import{_ as l,a0 as p,w as r,s as o,ao as d,I as i,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"何時需要關注 Linux 的內存用量？ | LCTT x X-CMD","titleTemplate":false,"description":"何時需要關注 Linux 的內存用量？ | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"何時需要關注 Linux 的內存用量？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"何時需要關注 Linux 的內存用量？ | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190513 When to be concerned about memory levels on Linux","title":"何時需要關注 Linux 的內存用量？","tag":"201907","desc":""},"relativePath":"201907/20190513 When to be concerned about memory levels on Linux.md","filePath":"[post].md"}'),u={name:"201907/20190513 When to be concerned about memory levels on Linux.md"};function h(b,s,c,m,g,k){const n=p("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="何時需要關注-linux-的內存用量" tabindex="-1">何時需要關注 Linux 的內存用量？ <a class="header-anchor" href="#何時需要關注-linux-的內存用量" aria-label="Permalink to “何時需要關注 Linux 的內存用量？”">​</a></h1><blockquote><p>Linux 上的內存管理很複雜。儘管使用率高但未必存在問題。你也應當關注一些其他的事情。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201907/06/173913n6rjbxwj6bfrjxwx.jpg" alt=""></p><p>在 Linux 上用光內存通常並不意味着存在嚴重的問題。為什麼？因為健康的 Linux 系統會在內存中緩存磁盤活動，基本上佔用掉了未被使用的內存，這顯然是一件好事情。</p><p>換句話説，它不讓內存浪費掉。使用空閒的內存增加磁盤訪問速度，並且不佔用運行中應用程序的內存。你也能夠想到，使用這種內存緩存比起直接訪問硬盤驅動器（HDD）快上數百倍，也比明顯快於直接訪問固態硬盤驅動。內存佔滿或幾乎佔滿通常意味着系統正在儘可能高效地運行當中 —— 並不是運行中遇到了問題。</p><h3 id="緩存如何工作" tabindex="-1">緩存如何工作 <a class="header-anchor" href="#緩存如何工作" aria-label="Permalink to “緩存如何工作”">​</a></h3><p>磁盤緩存簡單地意味着系統充分利用未使用的資源（空閒內存）來加速磁盤讀取與寫入。應用程序不會失去任何東西，並且大多數時間裏能夠按需求獲得更多的內存。此外，磁盤緩存不會導致應用程序轉而使用交換分區。反而，用作磁盤緩存的內存空間當被需要時會立即歸還，並且磁盤內容會被更新。</p><h3 id="主要和次要的頁故障" tabindex="-1">主要和次要的頁故障 <a class="header-anchor" href="#主要和次要的頁故障" aria-label="Permalink to “主要和次要的頁故障”">​</a></h3><p>Linux 系統通過分割物理內存來為進程分配空間，將分割成的塊稱為“頁”，並且映射這些頁到每個進程的虛擬內存上。不再會用到的頁也許會從內存中移除，儘管相關的進程還在運行。當進程需要一個沒有被映射或沒在內存中頁時，故障便會產生。所以，這個“<ruby>故障<rt>fault</rt></ruby>”並不意味着“<ruby>錯誤<rt>error</rt></ruby>”而是“<ruby>不可用<rt>unavailables</rt></ruby>”，並且故障在內存管理中扮演者一個重要的角色。</p><p>次要故障意味着在內存中的頁未分配給請求的進程，或未在內存管理單元中標記為出現。主要故障意味着頁沒有保留在內存中。</p><p>如果你想切身感受一下次要頁故障和主要頁故障出現的頻率，像這樣試一下 <code>ps</code> 命令。注意我們要的是與頁故障和產生它的命令相關的項。輸出中省略了很多行。<code>MINFL</code> 顯示出次要故障的數目，而 <code>MAJFL</code> 表示了主要故障的數目。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -eo min_flt,maj_flt,cmd</span></span>
<span class="line"><span> MINFL  MAJFL CMD</span></span>
<span class="line"><span>230760    150 /usr/lib/systemd/systemd --switched-root --system --deserialize 18</span></span>
<span class="line"><span>     0      0 [kthreadd]</span></span>
<span class="line"><span>     0      0 [rcu_gp]</span></span>
<span class="line"><span>     0      0 [rcu_par_gp]</span></span>
<span class="line"><span>     0      0 [kworker/0:0H-kblockd]</span></span>
<span class="line"><span>   ...</span></span>
<span class="line"><span>   166     20 gpg-agent --homedir /var/lib/fwupd/gnupg --use-standard-socket --daemon</span></span>
<span class="line"><span>   525      1 /usr/libexec/gvfsd-trash --spawner :1.16 /org/gtk/gvfs/exec_spaw/0</span></span>
<span class="line"><span>  4966      4 /usr/libexec/gnome-terminal-server</span></span>
<span class="line"><span>  3617      0 bash</span></span>
<span class="line"><span>     0      0 [kworker/1:0H-kblockd]</span></span>
<span class="line"><span>   927      0 gdm-session-worker [pam/gdm-password]</span></span></code></pre></div><p>彙報單一進程，你可以嘗試這樣的命令（LCTT 譯註：參數裏面的 <code>1</code> 是要查看的進程的 PID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -o min_flt,maj_flt 1</span></span>
<span class="line"><span> MINFL  MAJFL</span></span>
<span class="line"><span>230064    150</span></span></code></pre></div><p>你也可以添加其他的顯示字段，例如進程所有者的 UID 和 GID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -o min_flt,maj_flt,cmd,args,uid,gid 1</span></span>
<span class="line"><span> MINFL  MAJFL CMD                         COMMAND                       UID   GID</span></span>
<span class="line"><span>230064    150 /usr/lib/systemd/systemd -- /usr/lib/systemd/systemd --     0     0</span></span></code></pre></div><h3 id="多少才算滿" tabindex="-1">多少才算滿？ <a class="header-anchor" href="#多少才算滿" aria-label="Permalink to “多少才算滿？”">​</a></h3><p>一種較好的方法來掌握內存究竟使用了多少是用 <code>free -m</code> 命令。<code>-m</code> 選項指定了數字的單位是 <ruby>MiB<rt>mebibyte</rt></ruby> 而不是字節。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -m</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3244        3069          35          49         140         667</span></span>
<span class="line"><span>Swap:          3535           0        3535</span></span></code></pre></div><p>注意 <code>free</code>（未使用）的內存可能會不足，而 <code>available</code>（可用於啓動新的應用）會顯示更大的數量。這兩者的區別值得我們去關注。<ruby>可用<rt>available</rt></ruby>意味着它可以在需要時恢復使用，而<ruby>空閒<rt>free</rt></ruby>意味着現在就能夠使用。</p><h3 id="什麼時候要擔心" tabindex="-1">什麼時候要擔心 <a class="header-anchor" href="#什麼時候要擔心" aria-label="Permalink to “什麼時候要擔心”">​</a></h3><p>如果 Linux 系統上的性能表現良好 —— 應用程序響應度高，命令列沒有顯示出問題 —— 很可能系統狀況良好。記住，一些應用也許會出於某種原因而變慢，但它不影響整個系統。</p><p>過多的硬故障也許表明確實存在問題，但要將其與觀察到的性能相比較。</p><p>一個好的方法是當可用內存接近 0 或者“<ruby>用作交換<rt>swap used</rt></ruby>”項顯著增長或波動時開始擔心。如果“可用”項佔總內存可用量的百分比合理，那麼就無需擔心，就像下面的例子那樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -m</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3244        3069          35          49         140         667</span></span>
<span class="line"><span>Swap:          3535           0        3535</span></span></code></pre></div><h3 id="linux-性能很複雜" tabindex="-1">Linux 性能很複雜 <a class="header-anchor" href="#linux-性能很複雜" aria-label="Permalink to “Linux 性能很複雜”">​</a></h3><p>拋開這些不説，Linux 系統上的內存可能會變滿，並且性能可能會降低。當系統出現問題時不要僅將單一的內存使用報告作為指標。</p><p>Linux 系統的內存管理很複雜，因為它採取的措施需要確保系統資源得到最好的利用。不要受到一開始內存佔滿的欺騙，使你認為系統存在問題，但實際上並沒有。</p><hr>`,29)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3394603/when-to-be-concerned-about-memory-levels-on-linux.html"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3394603/when-to-be-concerned-about-memory-levels-on-linux.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/LuuMing"},{default:t(()=>[...s[4]||(s[4]=[a("LuuMing",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const L=l(u,[["render",h]]);export{y as __pageData,L as default};
